4061	static void lp_tick(void)
4062	{
4063	    uint32_t dt;
4064	
4065	    if (!LP.active) {
4066	        return;
4067	    }
4068	    dt = lv_tick_get() - LP.t0;
4069	    {
4070	        int p = dt >= LP.dur ? 100 : (int)(dt * 100 / LP.dur);
4071	
4072	        if (p != LP.pct) {
4073	            LP.pct = p;
4074	            lp_update_ui();
4075	        }
4076	        if (p >= 100) {
4077	            lp_fire();
4078	        }
4079	    }
4080	}
