4113	static void do_short(int key)
4114	{
4115	    if (s_screen == SCR_SHUTDOWN) {
4116	        if (s_power_phase == 0) {
4117	            if (key == 1) {
4118	                s_power_phase = 1;
4119	                s_power_ticks = 0;
4120	                rebuild();
4121	            } else {
4122	                s_screen = SCR_POWER;
4123	                s_busy = false;
4124	                rebuild();
4125	            }
4126	        } else if (s_power_phase == 2 && key == 1 && s_power_ticks >= 2) {
4127	            s_screen = SCR_DIAL;
4128	            s_power_phase = 0;
4129	            s_busy = false;
4130	            rebuild();
4131	        }
4132	        return;
4133	    }
4134	    if (s_screen == SCR_RIDE && s_end_confirm) {
4135	        if (key == 1) {
4136	            s_end_confirm = false;
4137	            ride_finish();
4138	            s_screen = SCR_DIAL;
4139	            s_busy = false;
4140	            rebuild();
4141	        } else {
4142	            s_end_confirm = false;
4143	            rebuild();
4144	        }
4145	        return;
4146	    }
4147	    if (key == 1) {
4148	        if (screen_is_setlist(s_screen)) {
4149	            setl_move(1);
4150	            return;
4151	        }
4152	        switch (s_screen) {
4153	            case SCR_DIAL: dial_rotate_next(); break;
4154	            case SCR_RIDE:
4155	                s_ride_page = (s_ride_page + 1) % 3;
4156	                ride_page_types();
4157	                ride_refresh();
4158	                break;
4159	            case SCR_NAV:
4160	                /* 导航页 KEY1 短：路线来源（GPX / 坐标点 / 常用点）；
4161	                 * KEY1 长：导航中 → 本次导航；未导航 → 海拔详情。 */
4162	                s_sub_sel = 0;
4163	                s_screen = SCR_ROUTE_SRC;
4164	                s_busy = false;
4165	                rebuild();
4166	                break;
4167	            case SCR_RECORD:
4168	                if (s_rec_sel + 1 < (s_rec_n < 4 ? s_rec_n : 4)) {
4169	                    s_rec_sel++;
4170	                    rec_sel_move(true);
4171	                    rec_rows();
4172	                }
4173	                break;
4174	            case SCR_ABOUT:
4175	                s_about_sel = (s_about_sel + 1) % 5;
4176	                about_focus_apply();
4177	                break;
4178	            default:
4179	                break;
4180	        }
4181	    } else {
4182	        go_back();
4183	    }
4184	}
