4186	/* ── 电源键（键盘 ↑）────────────────────────────────────────────────
4187	 *
4188	 * 与 KEY1/KEY2 的 LP 状态机分开，任何屏都可用（真长按，按按住时长判定）：
4189	 *   短按（松手 < 800 ms）  熄屏 / 亮屏切换（SCR_IDLE，旧 helm_idle 语义）
4190	 *   长按（按住 ≥ 800 ms）  关机确认（SCR_SHUTDOWN phase 0，旧 helm_pwr 语义）
4191	 *   关机黑屏（phase 2）    按一下 = 开机回盘面
4192	 *
4193	 * 熄屏时按 ↑ 先唤醒：这次按下/抬起整对吃掉，避免抬起又被当成短按关回去。 */
4194	#define PWR_LONG_MS 800
4195	
4196	static struct {
4197	    bool down;
4198	    bool fired;
4199	    bool ignore_up;
4200	    uint32_t t0;
4201	} PWR;
4202	
4203	static bool s_keylog;   /* SIM_HELM_KEYLOG=1：每次按键/动作打一行（取证用） */
4204	
4205	static void keylog(const char *fmt, ...)
4206	{
4207	    va_list ap;
4208	
4209	    if (!s_keylog) {
4210	        return;
4211	    }
4212	    printf("helm-key: ");
4213	    va_start(ap, fmt);
4214	    vprintf(fmt, ap);
4215	    va_end(ap);
4216	    putchar('\n');
4217	    fflush(stdout);
4218	}
