4259	static void pwr_event(bool down)
4260	{
4261	    if (down) {
4262	        if (PWR.down) {
4263	            return;             /* 自动重复已在上游去重，这里兜底 */
4264	        }
4265	        if (s_screen == SCR_IDLE ||
4266	            (s_screen == SCR_SHUTDOWN && s_power_phase == 2)) {
4267	            pwr_wake();
4268	            PWR.ignore_up = true;
4269	            keylog("POWER down -> wake (%s)", SCR_NAME[s_screen]);
4270	            return;
4271	        }
4272	        if (s_screen == SCR_SHUTDOWN) {
4273	            PWR.ignore_up = true;   /* 确认/进度页：电源键不参与 */
4274	            keylog("POWER down ignored (shutdown phase %d)", s_power_phase);
4275	            return;
4276	        }
4277	        if (LP.active) {
4278	            PWR.ignore_up = true;
4279	            keylog("POWER down ignored (LP active)");
4280	            return;
4281	        }
4282	        PWR.down = true;
4283	        PWR.fired = false;
4284	        PWR.t0 = lv_tick_get();
4285	        keylog("POWER down screen=%s", SCR_NAME[s_screen]);
4286	        return;
4287	    }
4288	
4289	    if (PWR.ignore_up) {
4290	        PWR.ignore_up = false;
4291	        keylog("POWER up consumed (wake)");
4292	        return;
4293	    }
4294	    if (!PWR.down) {
4295	        return;
4296	    }
4297	    PWR.down = false;
4298	    {
4299	        const uint32_t held = lv_tick_get() - PWR.t0;
4300	
4301	        hint_clear();
4302	        if (PWR.fired) {
4303	            PWR.fired = false;
4304	            keylog("POWER up held=%ums (shutdown already fired)", held);
4305	            return;
4306	        }
4307	        if (held >= PWR_LONG_MS) {
4308	            keylog("POWER up held=%ums -> shutdown", held);
4309	            pwr_shutdown_confirm();
4310	        } else {
4311	            keylog("POWER up held=%ums -> sleep", held);
4312	            pwr_sleep();
4313	        }
4314	    }
4315	}
