793	/** 自动暂停：速度 < 2 km/h 连续 10 s 触发；>= 2.5 km/h 自动恢复。 */
794	#define AUTO_PAUSE_ENTER_KMH 2.0
795	#define AUTO_PAUSE_EXIT_KMH  2.5
796	#define AUTO_PAUSE_HOLD_S    10
797	
798	static void ride_step(void)
799	{
800	    R.seed = R.seed * 1103515245u + 12345u;
801	    R.t += 1.0;
802	    {
803	        const double n = (double)((R.seed >> 16) & 0x7FFF) / 32767.0 - 0.5;
804	        double sp = 22.5 + 5.5 * sin(R.t / 8.0) + 1.6 * n;
805	
806	        /* 演示语义：每 60 s 有一个 14 s 的“红灯/推车”段（速度 0），
807	         * 自动暂停在静止 10 s 后触发、放行后自动恢复。 */
808	        if (fmod(R.t, 60.0) >= 46.0) {
809	            sp = 0.0;
810	        }
811	        if (sp > 0.0 && sp < 8.0) sp = 8.0;
812	        if (sp > 45.0) sp = 45.0;
813	        R.target = sp;
814	        if (R.paused) {
815	            R.speed = 0.0;
816	            R.cadence = 0;
817	            R.power = 0;
818	            if (R.hr > 96) R.hr--;
819	            return;
820	        }
821	        R.speed = sp;
822	        R.dist_km += sp / 3600.0;
823	        R.hr = 126 + (int)(sp * 1.05) + (int)(3.0 * n);
824	        R.cadence = sp <= 0.0 ? 0 : 78 + (int)(sp * 0.5) + (int)(4.0 * n);
825	        R.power = sp <= 0.0 ? 0 : (int)(120.0 + sp * 2.6 + 10.0 * n);
826	        R.elevation = 326 + (int)(9.0 * sin(R.t / 21.0));
827	        if (n > 0.28) {
828	            R.ascent += 1;
829	        }
830	        R.cal = (int)(R.dist_km * 32.0);
831	        if (R.speed > R.max) {
832	            R.max = R.speed;
833	        }
834	        R.avg = (R.elapsed_s > 0)
835	                    ? R.dist_km / ((double)R.elapsed_s / 3600.0)
836	                    : R.speed;
837	    }
838	    {
839	        const double s = R.speed;
840	        const int bin = (s < 15.0) ? 0 : (s < 25.0) ? 1 : (s < 35.0) ? 2
841	                      : (s < 45.0) ? 3 : 4;
842	
843	        R.hist[bin]++;
844	    }
845	}
