847	/** 1 Hz 骑行推进（暂停时停表/停里程；自动暂停判定用未门控速度）。 */
848	static void ride_advance_1s(void)
849	{
850	    if (!R.active) {
851	        return;
852	    }
853	    if (!R.paused) {
854	        R.elapsed_s++;      /* 先记这一秒，ride_step() 的均速用同一分母 */
855	    }
856	    ride_step();
857	    if (!R.paused && R.target < AUTO_PAUSE_ENTER_KMH) {
858	        R.still_s++;
859	        if (R.still_s >= AUTO_PAUSE_HOLD_S) {
860	            R.paused = true;
861	            R.auto_paused = true;
862	            R.speed = 0.0;
863	            R.cadence = 0;
864	            R.power = 0;
865	            toast("自动暂停 · 速度低于 2 km/h");
866	        }
867	    } else if (!R.paused) {
868	        R.still_s = 0;
869	    }
870	    if (R.paused && R.auto_paused && R.target >= AUTO_PAUSE_EXIT_KMH) {
871	        R.paused = false;
872	        R.auto_paused = false;
873	        R.still_s = 0;
874	        toast("自动继续");
875	    }
876	}
