235	static int xkey_to_sim_key(KeySym ks)
236	{
237	    switch (ks) {
238	        case XK_Left:
239	        case XK_1:
240	            return 1;
241	        case XK_Right:
242	        case XK_2:
243	            return 2;
244	        case XK_Up:
245	        case XK_3:
246	            return 3;
247	        default:
248	            return 0;
249	    }
250	}
