5189	static void tour_tick(void)
5190	{
5191	    if (!s_tour_on) {
5192	        return;
5193	    }
5194	    s_tour_frame++;
5195	    while (s_tour_idx < (int)(sizeof(TOUR) / sizeof(TOUR[0])) &&
5196	           TOUR[s_tour_idx].f <= (int)s_tour_frame) {
5197	        const tour_ev_t *e = &TOUR[s_tour_idx];
