5201	            tour_shot(e->a);
5202	        } else {
5203	            sim_display_inject_key(e->a, e->b != 0);
5204	        }
5205	    }
5206	    if (s_tour_idx >= (int)(sizeof(TOUR) / sizeof(TOUR[0]))) {
5207	        s_tour_on = false;
5208	    }
5209	}
