1281	static void dial_build(void)
1282	{
1283	    memset(&UD, 0, sizeof(UD));
1284	    s_screen = SCR_DIAL;
1285	    d_bg(s_scr, P_PAPER);
1286	    TOP(s_scr, "模式", "01 / 04");
1287	    UD.top_l = lv_obj_get_child(s_scr, 0);
1288	    UD.top_r = lv_obj_get_child(s_scr, 1);
1289	
1290	    UD.cx = DIAL_CX;
1291	    UD.cy = DIAL_CY;
1292	    UD.d = DIAL_D;
1293	    s_angle = s_mode * 90;
1294	    UD.angle = s_angle;
1295	
1296	    /* 整圈未选轨道 + 选中扇区（浅 20% + 深色 2px 外沿）。 */
1297	    UD.ring = RING(s_scr, UD.cx, UD.cy, UD.d, 2, P_TRACK);
1298	    dial_sector(s_mode, LV_OPA_COVER, &UD.fill, &UD.trk);
1299	
1300	    /* 24 刻度：每 15°，整点 3px。 */
1301	    for (int i = 0; i < 24; i++) {
1302	        const bool major = (i % 6 == 0);
1303	
1304	        UD.tick[i] = LINE(s_scr, UD.tick_pts[i], 2, major ? 3 : 1,
1305	                          major ? P_INK : P_TICK);
1306	    }
1307	    /* 舵柄：中心到外圈 + 8px 横杆。 */
1308	    UD.ptr = LINE(s_scr, UD.ptr_pts, 2, 3, P_INK);
1309	    UD.cross = LINE(s_scr, UD.cross_pts, 2, 3, P_INK);
1310	
1311	    /* 盘心：图标底 + 模式名 / 描述 / 主值 / 副行，装进一个容器方便整体淡入。 */
1312	    UD.hub = lv_obj_create(s_scr);
1313	    lv_obj_remove_style_all(UD.hub);
1314	    lv_obj_set_pos(UD.hub, 40, 84);
1315	    lv_obj_set_size(UD.hub, 160, 108);
1316	    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_SCROLLABLE);
1317	    lv_obj_remove_flag(UD.hub, LV_OBJ_FLAG_CLICKABLE);
1318	
1319	    {
1320	        /* 标题：文字 160 宽居中；20px 图标由 dial_title_layout() 摆到左侧。 */
1321	        UD.chip = NULL;
1322	        UD.icon = hfi_create_px(UD.hub, mode_icon(s_mode), 20, 0, 0,
1323	                                C_DEEP[s_mode]);
1324	        UD.name = LW(UD.hub, "", PX_TITLE, P_INK, 0, 0, 160,
1325	                     LV_TEXT_ALIGN_CENTER);
1326	    }
1327	    UD.desc = LW(UD.hub, "", PX_SMALL, P_MUTE, 0, 38, 160,
1328	                 LV_TEXT_ALIGN_CENTER);
1329	    {
1330	        /* 22px 数字 + 11px 单位：共用基线（hub_value_layout）。 */
1331	        UD.value = L(UD.hub, "", PX_VALUE, P_INK, 0, 55);
1332	        UD.unit = L(UD.hub, "", PX_MICRO, P_MUTE, 0, 66);
1333	    }
1334	    HAIR(UD.hub, 64, 87, 32);
1335	    UD.sub = LW(UD.hub, "", PX_MICRO, P_MUTE, 0, 92, 160,
1336	                LV_TEXT_ALIGN_CENTER);
1337	
1338	    /* 模式名：4 个方位，选中 15px。半径 99：文字墨迹内缘 r≈83，
1339	     * 与舵柄最外墨迹 r≈73 留 10px 安全距（脚本断言见证据）。 */
1340	    {
1341	        static const int lx[4] = { 0, 1, 0, -1 };
1342	        static const int ly[4] = { -1, 0, 1, 0 };
1343	
1344	        for (int i = 0; i < 4; i++) {
1345	            UD.labels[i] = LW(s_scr, mode_name(i), PX_SMALL, P_MUTE,
1346	                              DIAL_CX + lx[i] * 99 - 20,
1347	                              DIAL_CY + ly[i] * 99 - 8,
1348	                              40, LV_TEXT_ALIGN_CENTER);
1349	        }
1350	    }
1351	
1352	    /* 骑行中标记（顶栏，开始骑行后才出现）。 */
1353	    UD.live_bar = B(s_scr, 76, 15, 3, 10, C_DEEP[M_RECORD],
1354	                    LV_OPA_COVER, 1);
1355	    UD.live = L(s_scr, "骑行中", PX_MICRO, P_MUTE, 84, 13);
1356	    lv_obj_add_flag(UD.live, LV_OBJ_FLAG_HIDDEN);
1357	    lv_obj_add_flag(UD.live_bar, LV_OBJ_FLAG_HIDDEN);
