    snprintf(ub[0], sizeof(ub[0]), "%s", unit_speed());
    snprintf(ub[1], sizeof(ub[1]), "%s", unit_speed());
    snprintf(ub[2], sizeof(ub[2]), "%s", unit_dist());
    snprintf(ub[3], sizeof(ub[3]), "");
    snprintf(ub[4], sizeof(ub[4]), "bpm");
    snprintf(ub[5], sizeof(ub[5]), "rpm");
    snprintf(ub[6], sizeof(ub[6]), "m");
    snprintf(ub[7], sizeof(ub[7]), "%s", grade_unit());
    for (int i = 0; i < 8; i++) {
