{"file_path": "/home/jinsc/SDK/vela/lvgl_sim/src/scene_helm.c", "new_string": "/* ── 电源键（键盘 ↑）────────────────────────────────────────────────
 *
 *   单击（<400 ms）       无反应（只记日志；双击的第一次）
 *   双击（间隔 <300 ms）  熄屏（SCR_IDLE）
 *   长按（≥800 ms）       弹「确认关机？」（← 取消 / → 确认）
 *   熄屏 / 关机黑屏       按任意键或触摸唤醒；这一次输入不触发功能
 *   长按进度              底部红色填充条 + 百分比，松手取消
 */
static struct {
    bool down;
    bool fired;
    bool consume_up;
    bool last_click_valid;
    bool dbl;
    uint32_t t0;
    uint32_t last_click;
    lv_obj_t *bar;
} PWR;

static bool s_keylog;   /* SIM_HELM_KEYLOG=1：每次按键/动作打一行（取证用） */

static void keylog(const char *fmt, ...)
{
    va_list ap;

    if (!s_keylog) {
        return;
    }
    printf("helm-key: ");
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    putchar('\n');
    fflush(stdout);
}

static void pwr_wake(void)
{
    if (s_screen == SCR_SHUTDOWN) {
        s_screen = SCR_DIAL;
        s_power_phase = 0;
        s_power_ticks = 0;
    } else {
        s_screen = s_idle_return;
    }
    s_idle_s = 0;
    s_busy = false;
    rebuild();
}

static void pwr_sleep(void)
{
    if (s_screen == SCR_IDLE || s_screen == SCR_SHUTDOWN) {
        return;
    }
    s_idle_return = s_screen;
    s_idle_s = 0;
    s_screen = SCR_IDLE;
    s_busy = false;
    rebuild();
}

/* ── 模态弹窗 ──────────────────────────────────────────────────── */

static void modal_draw(void)
{
    lv_obj_t *card;
    uint32_t accent;
    const char *title;
    const char *sub;
    const char *left = NULL;
    const char *right = "→ 关闭";
    char sbuf[64];

    if (s_modal == MODAL_NONE) {
        return;
    }
    if (s_modal == MODAL_SHUTDOWN) {
        accent = P_RED;
        title = "确认关机？";
        sub = "骑行记录会先保存";
        left = "← 取消";
        right = "→ 确认";
    } else if (s_modal == MODAL_SAVE_ASK) {
        accent = C_DEEP[M_RECORD];
        title = "保存本次骑行？";
        sub = "不保存将丢弃本次记录";
        left = "← 不保存";
        right = "→ 保存";
    } else {
        accent = s_modal_saved ? C_DEEP[M_RIDE] : P_MUTE;
        title = s_modal_saved ? "已保存" : "未保存";
        snprintf(sbuf, sizeof(sbuf),
                 s_modal_saved ? "本次 %.1f %s · 共 %d 次记录"
                               : "本次已丢弃 · 共 %d 次记录",
                 s_modal_saved ? conv_dist(R.dist_km) : 0.0,
                 s_modal_saved ? unit_dist() : "", s_rec_n);
        sub = sbuf;
    }

    /* 40% 黑色遮罩：弹窗期间底层页面只作背景，不再接受按键。 */
    (void)B(s_scr, 0, 0, 240, 320, 0x000000u, LV_OPA_40, 0);
    card = B(s_scr, 12, 88, 216, 144, P_CARD, LV_OPA_COVER, 12);
    lv_obj_set_style_border_width(card, 1, 0);
    lv_obj_set_style_border_color(card, lv_color_hex(P_HAIR), 0);
    lv_obj_set_style_border_opa(card, LV_OPA_COVER, 0);
    (void)B(card, 0, 10, 4, 26, accent, LV_OPA_COVER, 2);
    (void)L(card, title, PX_VALUE, P_INK, 16, 10);
    (void)L(card, sub, PX_MICRO, P_MUTE, 16, 40);
    HAIR(card, 12, 62, 192);

    if (left != NULL) {
        (void)B(card, 12, 72, 22, 22, C_LIGHT[M_SET], LV_OPA_COVER, 6);
        (void)L(card, "←", PX_SMALL, P_INK, 19, 74);
        (void)L(card, left + 1, PX_BODY, P_INK, 40, 72);
        (void)B(card, 12, 100, 22, 22, P_TRACK, LV_OPA_COVER, 6);
        (void)L(card, "→", PX_SMALL, P_INK, 19, 102);
        (void)L(card, right + 1, PX_BODY, P_INK, 40, 100);
    } else {
        (void)B(card, 12, 72, 22, 22, C_LIGHT[M_RIDE], LV_OPA_COVER, 6);
        (void)L(card, "→", PX_SMALL, P_INK, 19, 74);
        (void)L(card, right + 1, PX_BODY, P_INK, 40, 72);
    }
}

static void modal_open(modal_t m)
{
    s_modal = m;
    s_modal_key = 0;
    s_busy = false;
    rebuild();
}

static void modal_action(int key)
{
    switch (s_modal) {
        case MODAL_SHUTDOWN:
            s_modal = MODAL_NONE;
            if (key == 1) {
                keylog("modal shutdown: cancel");
                s_busy = false;
                rebuild();
            } else {
                keylog("modal shutdown: confirm -> poweroff");
                s_power_mode = 0;
                s_power_phase = 1;
                s_power_ticks = 0;
                s_screen = SCR_SHUTDOWN;
                s_busy = false;
                rebuild();
            }
            break;
        case MODAL_SAVE_ASK:
            if (key == 1) {
                keylog("modal save: discard ride");
                R.active = false;
                R.paused = false;
                R.auto_paused = false;
                R.rec = false;
                s_end_confirm = false;
                s_modal_saved = false;
            } else {
                keylog("modal save: save ride");
                (void)ride_finish();
                s_modal_saved = true;
            }
            s_modal = MODAL_SAVE_DONE;
            s_screen = SCR_DIAL;
            s_busy = false;
            rebuild();
            break;
        case MODAL_SAVE_DONE:
            if (key == 2) {
                keylog("modal saved: close");
                s_modal = MODAL_NONE;
                s_busy = false;
                rebuild();
            }
            break;
        default:
            break;
    }
}

static void modal_key_event(int key, bool down)
{
    if (key == 3) {
        keylog("modal: POWER ignored (modal)");
        return;
    }
    if (down) {
        if (s_modal_key == 0) {
            s_modal_key = key;
            s_modal_t0 = lv_tick_get();
        }
        return;
    }
    if (key != s_modal_key) {
        return;
    }
    s_modal_key = 0;
    if (lv_tick_get() - s_modal_t0 >= KEY_CLICK_MS) {
        keylog("modal: KEY%d press ignored (not a click)", key);
        return;
    }
    modal_action(key);
}

/* ── 电源键状态机 ──────────────────────────────────────────────── */

static void pwr_progress_clear(void)
{
    if (PWR.bar != NULL) {
        lv_obj_delete(PWR.bar);
        PWR.bar = NULL;
    }
    hint_clear();
}

static void pwr_progress_update(void)
{
    if (!PWR.down || PWR.fired) {
        return;
    }
    {
        const uint32_t held = lv_tick_get() - PWR.t0;
        int p = held >= KEY_LONG_MS ? 100 : (int)(held * 100 / KEY_LONG_MS);
        char buf[32];

        if (PWR.bar != NULL) {
            lv_obj_set_width(PWR.bar, p * 192 / 100);
        }
        snprintf(buf, sizeof(buf), "关机 · %d%%", p);
        hint_set(buf);
    }
}

static void pwr_event(bool down)
{
    if (down) {
        if (PWR.down) {
            return;             /* 自动重复已在上游去重，这里兜底 */
        }
        if (s_screen == SCR_IDLE ||
            (s_screen == SCR_SHUTDOWN && s_power_phase == 2)) {
            const scr_t from = s_screen;

            pwr_wake();
            PWR.consume_up = true;
            keylog("POWER click -> wake from %s (input consumed)", SCR_NAME[from]);
            return;
        }
        if (s_screen == SCR_SHUTDOWN) {
            PWR.consume_up = true;
            keylog("POWER down ignored (shutdown phase %d)", s_power_phase);
            return;
        }
        if (LP.active) {
            PWR.consume_up = true;
            keylog("POWER down ignored (LP active)");
            return;
        }
        PWR.down = true;
        PWR.fired = false;
        PWR.t0 = lv_tick_get();
        /* 双击判定：距上一次单击松手 <300 ms，则这次是双击的第二下。 */
        PWR.dbl = PWR.last_click_valid &&
                  (PWR.t0 - PWR.last_click < KEY_DBL_MS);
        PWR.bar = B(s_scr, 24, 317, 0, 3, P_RED, LV_OPA_COVER, 1);
        keylog("POWER down screen=%s dbl=%d", SCR_NAME[s_screen],
               PWR.dbl ? 1 : 0);
        pwr_progress_update();
        return;
    }

    if (PWR.consume_up) {
        PWR.consume_up = false;
        keylog("POWER up consumed (wake)");
        return;
    }
    if (!PWR.down) {
        return;
    }
    PWR.down = false;
    {
        const uint32_t held = lv_tick_get() - PWR.t0;

        pwr_progress_clear();
        if (PWR.fired) {
            PWR.fired = false;
            PWR.last_click_valid = false;
            keylog("POWER up held=%ums (long already fired)", held);
            return;
        }
        if (held < KEY_CLICK_MS) {
            if (PWR.dbl) {
                PWR.last_click_valid = false;
                keylog("POWER double click (gap<300ms) -> sleep");
                pwr_sleep();
            } else {
                PWR.last_click_valid = true;
                PWR.last_click = lv_tick_get();
                keylog("POWER click held=%ums (no-op)", held);
            }
        } else {
            PWR.last_click_valid = false;
            keylog("POWER press cancelled held=%ums", held);
        }
    }
}

static void pwr_tick(void)
{
    if (!PWR.down || PWR.fired) {
        return;
    }
    {
        const uint32_t held = lv_tick_get() - PWR.t0;

        pwr_progress_update();
        if (held >= KEY_LONG_MS) {
            PWR.fired = true;
            PWR.last_click_valid = false;
            pwr_progress_clear();
            keylog("POWER long held=%ums -> shutdown popup", held);
            modal_open(MODAL_SHUTDOWN);
        }
    }
