}

/** 状态徽章：导航 / 暂停 / REC。16×16 圆角底 + 16px 符号。 */
static void status_badge(int x, int kind)
{
    lv_obj_t *chip;
    lv_obj_t *sym;

    if (kind == 0) {                 /* 导航中 */
        chip = B(s_scr, x, 4, 16, 16, C_LIGHT[M_NAV], LV_OPA_COVER, 4);
        sym = scaled_icon(chip, HELM_ICON_NAV, 8, 8, 12, C_DEEP[M_NAV]);
        (void)sym;
    } else if (kind == 1) {          /* 暂停 */
        chip = B(s_scr, x, 4, 16, 16, C_LIGHT[M_RECORD], LV_OPA_COVER, 4);
        (void)B(chip, 4, 3, 3, 10, P_INK, LV_OPA_COVER, 1);
        (void)B(chip, 9, 3, 3, 10, P_INK, LV_OPA_COVER, 1);
    } else {                         /* REC（暂停时变灰） */
        const bool dim = R.paused;

        chip = B(s_scr, x, 4, 16, 16, dim ? P_CARD : 0xE8CCC4u,
                 LV_OPA_COVER, 4);
        (void)B(chip, 5, 5, 6, 6, dim ? P_TRACK : P_RED, LV_OPA_COVER, 3);
    }
}

static void statusbar_refresh(void)
{
    char buf[16];
    const bool low = s_batt < 20;
    const uint32_t bcol = low ? P_RED : P_INK;

    if (SB.time_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(SB.time_l, buf);

    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(SB.batt_l, buf);
    lv_obj_set_style_text_color(SB.batt_l, lv_color_hex(bcol), 0);
    lv_obj_set_style_text_color(SB.batt_i, lv_color_hex(bcol), 0);

    snprintf(buf, sizeof(buf), "%d", s_gps);
    lv_label_set_text(SB.gps_l, buf);
    lv_obj_set_style_text_color(SB.gps_i,
                                lv_color_hex(s_gps > 0 ? C_DEEP[M_NAV]
                                                       : P_TRACK), 0);
}

/** 建状态栏（环形页与骑行三页共用）。 */
static void statusbar_build(void)
{
    char buf[16];
    int bx = SB_BADGE_X;

    memset(&SB, 0, sizeof(SB));
    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 23, 240);

    /* 左：状态徽章（可并存），优先级 导航 > 暂停 > REC。 */
    if (s_nav_active) {
        status_badge(bx, 0);
        bx += SB_BADGE_STEP;
    }
    if (R.active && R.paused) {
        status_badge(bx, 1);
        bx += SB_BADGE_STEP;
    }
    if (R.active && R.rec) {
        status_badge(bx, 2);
    }

    /* 右：GPS 颗数。 */
    SB.gps_i = scaled_icon(s_scr, HELM_ICON_GPS, SB_GPS_CX, 12, 12,
                           s_gps > 0 ? C_DEEP[M_NAV] : P_TRACK);
    snprintf(buf, sizeof(buf), "%d", s_gps);
    SB.gps_l = L(s_scr, buf, PX_MICRO, P_INK, SB_GPS_TXT_X, 5);

    /* 右：外设三点（心率/功率/踏频；实心=已连，空心=未连）。 */
    status_dot(s_scr, SB_SENS_X0, 10, 5,
               s_sens_on[0] ? P_INK : P_TRACK, !s_sens_on[0]);
    status_dot(s_scr, SB_SENS_X0 + SB_SENS_STEP, 10, 5,
               s_sens_on[2] ? P_INK : P_TRACK, !s_sens_on[2]);
    status_dot(s_scr, SB_SENS_X0 + 2 * SB_SENS_STEP, 10, 5,
               s_sens_on[1] ? P_INK : P_TRACK, !s_sens_on[1]);

    /* 右：电量图标 + 百分比（<20% 数据红）。 */
    SB.batt_i = scaled_icon(s_scr, HELM_ICON_BATTERY, SB_BAT_CX, 12, 12,
                            s_batt < 20 ? P_RED : P_INK);
    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    SB.batt_l = L(s_scr, buf, PX_MICRO,
                  s_batt < 20 ? P_RED : P_INK, SB_BAT_TXT_X, 5);

    /* 右：时间。 */
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    SB.time_l = LW(s_scr, buf, PX_MICRO, P_INK, SB_TIME_X, 5, 29,
                   LV_TEXT_ALIGN_RIGHT);
}

