    (void)L(card, l1, PX_BODY, P_INK, 16, 44);
    (void)L(card, l2, PX_MICRO, P_MUTE, 16, 68);
    (void)L(card, hint, PX_MICRO, P_MUTE, 16, 90);
    HAIR(card, 16, 112, 168);
    if (lic != NULL) {
        modal_key_illus(card, 16, 134, lic, lact);
