 *   左组 10..96（图标 10/28/46/64/82，每个 14px，间隙 4）
 *   时间 102..138（盒宽 36 居中；字形 104..136）
 *   右组 156..228（电量图标 156..170、电量文本 172..200、
 *                  REC 204..210、NAV 214..228）
 *   左组右缘 96 < 时间字形左沿 104.2 - 8；右组左缘 156 > 时间字形右沿
 *   135.8 + 8；右组最右 228 = 内容坐标 216（右边距 12）。
 */
#define SB_L_X0      10
#define SB_L_C0      17
#define SB_L_STEP    18
#define SB_TIME_X    102
#define SB_TIME_W    36
#define SB_BAT_CX    163
#define SB_BAT_TXT_X 172
#define SB_BAT_TXT_W 28
#define SB_REC_X     204
#define SB_NAV_CX    221

typedef struct {
    lv_obj_t *time_l;
    lv_obj_t *batt_l;
    lv_obj_t *batt_i;
    lv_obj_t *rec_dot;
    lv_obj_t *nav_i;
} statusbar_ui_t;

static statusbar_ui_t SB;

static void status_dot(lv_obj_t *p, int x, int y, int d, uint32_t col,
                       bool hollow)
{
    lv_obj_t *o = B(p, x, y, d, d, col,
                    hollow ? LV_OPA_TRANSP : LV_OPA_COVER, d / 2);

    if (hollow) {
        lv_obj_set_style_border_width(o, 1, 0);
        lv_obj_set_style_border_color(o, lv_color_hex(col), 0);
        lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
    }
}

/** 20px 图标字形按比例缩到 px（10~14）。 */
static lv_obj_t *scaled_icon(lv_obj_t *p, helm_icon_t id, int cx, int cy,
                             int px, uint32_t col)
{
    lv_obj_t *ic = hfi_create_px(p, id, 20, cx, cy, col);

    lv_obj_set_style_transform_scale(ic, px * 256 / 20, 0);
    lv_obj_set_style_transform_pivot_x(ic, 10, 0);
    lv_obj_set_style_transform_pivot_y(ic, 10, 0);
    return ic;
}

/** BLE 没有对应字形：14px 手绘蓝牙符文（1px 折线），颜色表达连接状态。 */
static void ble_glyph(int cx, int cy, uint32_t col)
{
    lv_point_precise_t stem[2] = { { cx, cy - 6 }, { cx, cy + 6 } };
    lv_point_precise_t up[3] = { { cx, cy - 6 }, { cx + 4, cy - 2 },
                                 { cx - 3, cy + 2 } };
    lv_point_precise_t dn[3] = { { cx, cy + 6 }, { cx + 4, cy + 2 },
                                 { cx - 3, cy - 2 } };

    (void)LINE(s_scr, stem, 2, 1, col);
    (void)LINE(s_scr, up, 3, 1, col);
    (void)LINE(s_scr, dn, 3, 1, col);
}

/** 左组一个 14px 外设图标 + 3px 连接点（实心=已连，空心=未连）。 */
static void left_sensor(int idx, helm_icon_t id, bool on)
{
    const int cx = SB_L_C0 + idx * SB_L_STEP;
    uint32_t col = on ? P_INK : P_TRACK;

    (void)scaled_icon(s_scr, id, cx, 12, 14, col);
    status_dot(s_scr, cx + 4, 15, 3, col, !on);
}

static void statusbar_refresh(void)
{
    char buf[16];
    const bool low = s_batt < 20;
    const uint32_t bcol = low ? P_RED : P_INK;

    if (SB.time_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(SB.time_l, buf);

    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(SB.batt_l, buf);
    lv_obj_set_style_text_color(SB.batt_l, lv_color_hex(bcol), 0);
    lv_obj_set_style_text_color(SB.batt_i, lv_color_hex(bcol), 0);

    /* REC：记录中红点；暂停变灰；未记录隐藏。 */
    if (SB.rec_dot != NULL) {
        if (R.active && R.rec) {
            lv_obj_remove_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_bg_color(SB.rec_dot,
                                      lv_color_hex(R.paused ? P_TRACK : P_RED),
                                      0);
        } else {
            lv_obj_add_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
        }
    }
    /* NAV：导航中深蓝，未导航浅灰。 */
    if (SB.nav_i != NULL) {
        lv_obj_set_style_text_color(
            SB.nav_i, lv_color_hex(s_nav_active ? C_DEEP[M_NAV] : P_TRACK), 0);
    }
}

/** 建状态栏（环形页与骑行三页共用）。 */
static void statusbar_build(void)
{
    char buf[16];

    memset(&SB, 0, sizeof(SB));
    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 23, 240);

    /* 左组：GPS / BLE / 心率 / 功率 / 踏频（14px，4px 间隙）。 */
    (void)scaled_icon(s_scr, HELM_ICON_GPS, SB_L_C0, 12, 14,
                      s_gps > 0 ? P_INK : P_TRACK);
    status_dot(s_scr, SB_L_C0 + 4, 15, 3,
               s_gps > 0 ? P_INK : P_TRACK, s_gps <= 0);
    ble_glyph(SB_L_C0 + SB_L_STEP, 12, s_ble_on ? P_INK : P_TRACK);
    status_dot(s_scr, SB_L_C0 + SB_L_STEP + 4, 15, 3,
               s_ble_on ? P_INK : P_TRACK, !s_ble_on);
    left_sensor(2, HELM_ICON_HEART, s_sens_on[0]);
    left_sensor(3, HELM_ICON_SPEED, s_sens_on[2]);
    left_sensor(4, HELM_ICON_BIKE, s_sens_on[1]);

    /* 中间：时间 12px，盒 102..138 居中（中线 120）。 */
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    SB.time_l = LW(s_scr, buf, 12, P_INK, SB_TIME_X, 4, SB_TIME_W,
                   LV_TEXT_ALIGN_CENTER);

    /* 右组：电量（图标 + %）。 */
    SB.batt_i = scaled_icon(s_scr, HELM_ICON_BATTERY, SB_BAT_CX, 12, 14,
                            s_batt < 20 ? P_RED : P_INK);
    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    SB.batt_l = LW(s_scr, buf, PX_MICRO,
                   s_batt < 20 ? P_RED : P_INK, SB_BAT_TXT_X, 5,
                   SB_BAT_TXT_W, LV_TEXT_ALIGN_RIGHT);

    /* 右组：REC 红点（暂停灰 / 未记录隐藏）。 */
    SB.rec_dot = B(s_scr, SB_REC_X, 9, 6, 6, P_RED, LV_OPA_COVER, 3);

    /* 右组：NAV 图标（未导航浅灰）。 */
    SB.nav_i = scaled_icon(s_scr, HELM_ICON_NAV, SB_NAV_CX, 12, 14,
                           s_nav_active ? C_DEEP[M_NAV] : P_TRACK);

    statusbar_refresh();
}

