a=s.index('/* ── 共用状态栏（环形页 + 三个骑行页同一套；y=0..24，内容从 y≥24）──')
b=s.index('/** 三页指示点：y=26..33', a)
new = r'''/* ── 共用状态栏（环形页 + 三个骑行页同一套；y=0..24，内容从 y≥24）──
 *
 * 两簇对齐（按**墨迹**而不是对象框）：
 *   左簇：时间 + GPS BLE 心率 功率 踏频，墨迹 x0=12，时间→GPS 8px，图标间 4px；
 *   右簇：REC + NAV + 电量，墨迹 x1=216，REC→NAV 4px，NAV→电量 8px；
 *   两簇之间弹性空白（space-between）。
 *
 * 墨迹宽度来自 240×320 实测（见 statusbar_coords.md）：
 *   GPS 14 · BLE 12（8 字形 + 1 + 3 点）· 心率 14 · 功率 14 · 踏频 15
 *   REC 5 · NAV 10 · 电池图标 8 · 时间/电量文本用 12px/10px 文本宽度。
 */
#define INK_GAP_TIME 8
#define INK_GAP_ICON 4
#define SB_TIME_X    12
#define SB_REC_NAV_X 155
#define SB_REC_X     169
#define SB_NAV_CX    169
#define SB_BAT_CX    186
#define SB_BAT_TXT_X 192
#define SB_BAT_TXT_W 24
#define SB_MIN_BLANK 12

typedef struct {
    lv_obj_t *time_l;
    lv_obj_t *batt_l;
    lv_obj_t *batt_i;
    lv_obj_t *rec_dot;
    lv_obj_t *nav_i;
} statusbar_ui_t;

static statusbar_ui_t SB;

static void status_dot(lv_obj_t *p, int x, int y, int d, uint32_t col,
                       bool hollow)
{
    lv_obj_t *o = B(p, x, y, d, d, col,
                    hollow ? LV_OPA_TRANSP : LV_OPA_COVER, d / 2);

    if (hollow) {
        lv_obj_set_style_border_width(o, 1, 0);
        lv_obj_set_style_border_color(o, lv_color_hex(col), 0);
        lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
    }
}

/** 20px 图标字形按比例缩到 px（8~14）。 */
static lv_obj_t *scaled_icon(lv_obj_t *p, helm_icon_t id, int cx, int cy,
                             int px, uint32_t col)
{
    lv_obj_t *ic = hfi_create_px(p, id, 20, cx, cy, col);

    lv_obj_set_style_transform_scale(ic, px * 256 / 20, 0);
    lv_obj_set_style_transform_pivot_x(ic, 10, 0);
    lv_obj_set_style_transform_pivot_y(ic, 10, 0);
    return ic;
}

/** 按“墨迹左沿”放一个 14px 图标；cx_off = 墨迹左沿到对象中心的距离。
 *  dot_x = 连接点相对墨迹左沿的偏移（-1 = 不画）。 */
static void icon_at_ink(helm_icon_t id, int ink_x0, int ink_w, int cx_off,
                        int dot_x, bool on)
{
    uint32_t col = on ? P_INK : P_TRACK;

    (void)scaled_icon(s_scr, id, ink_x0 + cx_off, 12, 14, col);
    if (dot_x >= 0) {
        status_dot(s_scr, ink_x0 + dot_x, 16, 3, col, !on);
    }
    (void)ink_w;
}

/** 左簇墨迹布局：返回左簇最后一个墨迹 x1；pos[] 为各图标墨迹 x0（-1=隐藏）。 */
static int left_cluster_layout(int x0, bool ble, bool hr, bool pwr, bool cad,
                               int pos[5])
{
    const int w[5] = { 14, 12, 14, 14, 15 };
    const bool on[5] = { true, ble, hr, pwr, cad };
    int x = x0;
    int end = x - 1;

    for (int i = 0; i < 5; i++) {
        if (!on[i]) {
            pos[i] = -1;
            continue;
        }
        pos[i] = x;
        end = x + w[i] - 1;
        x = end + 1 + INK_GAP_ICON;
    }
    return end;
}

static void statusbar_refresh(void)
{
    char buf[16];
    const bool low = s_batt < 20;
    const uint32_t bcol = low ? P_RED : P_INK;

    if (SB.time_l == NULL) {
        return;
    }
    snprintf(buf, sizeof(buf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    lv_label_set_text(SB.time_l, buf);

    snprintf(buf, sizeof(buf), "%d%%", s_batt);
    lv_label_set_text(SB.batt_l, buf);
    lv_obj_set_style_text_color(SB.batt_l, lv_color_hex(bcol), 0);
    lv_obj_set_style_text_color(SB.batt_i, lv_color_hex(bcol), 0);

    /* REC：记录中红点；暂停变灰；未记录隐藏。 */
    if (SB.rec_dot != NULL) {
        if (R.active && R.rec) {
            lv_obj_remove_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_bg_color(SB.rec_dot,
                                      lv_color_hex(R.paused ? P_TRACK : P_RED),
                                      0);
        } else {
            lv_obj_add_flag(SB.rec_dot, LV_OBJ_FLAG_HIDDEN);
        }
    }
    /* NAV：导航中显示（深蓝），未导航隐藏。 */
    if (SB.nav_i != NULL) {
        if (s_nav_active) {
            lv_obj_remove_flag(SB.nav_i, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_text_color(SB.nav_i,
                                        lv_color_hex(C_DEEP[M_NAV]), 0);
        } else {
            lv_obj_add_flag(SB.nav_i, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

/** 建状态栏（环形页与骑行三页共用）。 */
static void statusbar_build(void)
{
    char tbuf[16];
    int time_end;
    int pos[5];
    bool show_ble = true;
    bool cluster_off = !s_sens_on[0] && !s_sens_on[1] && !s_sens_on[2];
    bool show_hr = !cluster_off;
    bool show_pwr = !cluster_off;
    bool show_cad = !cluster_off;
    bool show_nav = s_nav_active;
    bool show_rec = R.active && R.rec;
    int left_end;
    int right_left;
    int x0;

    memset(&SB, 0, sizeof(SB));
    (void)B(s_scr, 0, 0, 240, 24, P_PAPER, LV_OPA_COVER, 0);
    HAIR(s_scr, 0, 23, 240);

    /* ① 时间：墨迹 x0=12（12px，贴左）。 */
    snprintf(tbuf, sizeof(tbuf), "%d:%02d", (s_min / 60) % 24, s_min % 60);
    SB.time_l = LW(s_scr, tbuf, 12, P_INK, SB_TIME_X, 4,
                   text_width(tbuf, 12) + 2, LV_TEXT_ALIGN_LEFT);
    time_end = SB_TIME_X + text_width(tbuf, 12) - 1;

    /* ② 左簇墨迹布局 + 碰撞保护（隐藏顺序 踏频→功率→NAV→BLE）。 */
    x0 = time_end + 1 + INK_GAP_TIME;
    for (int guard = 0; guard < 5; guard++) {
        left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr,
                                       show_cad, pos);
        right_left = show_rec ? (show_nav ? SB_REC_NAV_X : SB_REC_X)
                              : (show_nav ? 164 : SB_BAT_CX - 4);
        if (right_left - left_end - 1 >= SB_MIN_BLANK) {
            break;
        }
        if (show_cad) {
            show_cad = false;
            printf("helm: statusbar collision -> hide cadence\n");
        } else if (show_pwr) {
            show_pwr = false;
            printf("helm: statusbar collision -> hide power\n");
        } else if (show_nav) {
            show_nav = false;
            printf("helm: statusbar collision -> hide NAV\n");
        } else if (show_ble) {
            show_ble = false;
            printf("helm: statusbar collision -> hide BLE\n");
        } else {
            break;
        }
    }
    left_end = left_cluster_layout(x0, show_ble, show_hr, show_pwr, show_cad,
                                   pos);

    if (pos[0] >= 0) {
        icon_at_ink(HELM_ICON_GPS, pos[0], 14, 6, 11, s_gps > 0);
    }
    if (pos[1] >= 0) {
        icon_at_ink(HELM_ICON_BLE, pos[1], 12, 4, 9, s_ble_on);
    }
    if (pos[2] >= 0) {
        icon_at_ink(HELM_ICON_HEART, pos[2], 14, 6, 11, s_sens_on[0]);
    }
    if (pos[3] >= 0) {
        icon_at_ink(HELM_ICON_SPEED, pos[3], 14, 6, 11, s_sens_on[2]);
    }
    if (pos[4] >= 0) {
        icon_at_ink(HELM_ICON_BIKE, pos[4], 15, 7, 12, s_sens_on[1]);
    }

    /* ③ 右簇：REC / NAV 以电量为锚点从右往左排。 */
    {
        int bat_x0 = SB_BAT_CX - 4;          /* 电池图标墨迹 182..189 */
        int nav_x0 = 164;                    /* NAV 墨迹 164..173 */
        int rec_x0 = show_nav ? SB_REC_NAV_X : SB_REC_X;

        if (show_nav) {
            SB.nav_i = scaled_icon(s_scr, HELM_ICON_NAV, SB_NAV_CX, 12, 14,
                                   C_DEEP[M_NAV]);
        }
        if (show_rec) {
            SB.rec_dot = B(s_scr, rec_x0, 9, 5, 5, P_RED, LV_OPA_COVER, 2);
        }
        SB.batt_i = scaled_icon(s_scr, HELM_ICON_BATTERY, SB_BAT_CX, 12, 10,
                                s_batt < 20 ? P_RED : P_INK);
        snprintf(tbuf, sizeof(tbuf), "%d%%", s_batt);
        SB.batt_l = LW(s_scr, tbuf, 10,
                       s_batt < 20 ? P_RED : P_INK, SB_BAT_TXT_X, 6,
                       SB_BAT_TXT_W, LV_TEXT_ALIGN_RIGHT);
        right_left = show_rec ? (show_nav ? SB_REC_NAV_X : SB_REC_X)
                              : (show_nav ? nav_x0 : bat_x0);
        (void)right_left;
        (void)nav_x0;
    }

    statusbar_refresh();
}

